#Requires -Version 7.6
# SYNTHETIC OFFLINE FIXTURES ONLY (MOCK / NOT_LIVE). Every task, canonical file, packet, issue, note,
# operation, admission, journal and fake gh executable below is invented for this test and lives under
# EvidenceRoot. The ONLY external substitution is the consumer's own ProcessRunner seam, which records
# arguments and read/edit counts; no real gh, network, account, credential, vault or live queue is used.
# Passing proves offline composed behavior of the REAL canonical UPDATE writer (rows generated by
# Invoke-CanonicalLifecycleUpdateCommit) feeding the REAL delivery consumer (Invoke-AdmittedTaskLifecycleUpdate),
# including partial-failure recovery and stale-input rejection. It is not host admission, not live
# GitHub/Obsidian delivery and not proof that the whole of #67 is complete.
param(
  [Parameter(Mandatory)][string]$SourcePath,
  [Parameter(Mandatory)][string]$EvidenceRoot
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'

function Get-Sha { param([string]$Path) [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([IO.File]::ReadAllBytes($Path))).ToLowerInvariant() }
function Get-TextSha { param([string]$Text) [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.UTF8Encoding]::new($false).GetBytes($Text))).ToLowerInvariant() }

$SourceRoot=[IO.Path]::GetFullPath($SourcePath).TrimEnd('\','/')
$Ev=[IO.Path]::GetFullPath($EvidenceRoot).TrimEnd('\','/')
function Get-SourceFile { param([string[]]$Parts) $p=$SourceRoot; foreach($x in $Parts){$p=Join-Path $p $x}; [IO.Path]::GetFullPath($p) }
$CommitFile=Get-SourceFile 'scripts','github','commit-canonical-lifecycle-update.ps1'
$EnqueueFile=Get-SourceFile 'scripts','github','enqueue-canonical-lifecycle-update.ps1'
$ConsumerFile=Get-SourceFile 'scripts','github','task-lifecycle-mirror-consumer.ps1'
$TransportFile=Join-Path (Split-Path -Parent $ConsumerFile) 'github-cli-transport216.ps1'
$ReconcileFile=Get-SourceFile 'scripts','github','lifecycle-compat','continuity','reconcile.ps1'
$CaptureFile=Get-SourceFile 'scripts','github','lifecycle-compat','dispatch','reviewed-blocked-capture.ps1'
$RequiredDeps=@($CommitFile,$EnqueueFile,$ConsumerFile,$TransportFile,$ReconcileFile,$CaptureFile)
$ReferenceDeps=@(
  (Get-SourceFile 'tests','github','canonical-lifecycle-update-commit.tests.ps1'),
  (Get-SourceFile 'tests','github','lifecycle-failure-journal.tests.ps1'),
  (Get-SourceFile 'tests','github','lifecycle-initial-read-retry.tests.ps1'),
  (Get-SourceFile 'scripts','github','README-lifecycle-update.md'))

try {
  foreach($f in $RequiredDeps){ if(-not [IO.File]::Exists($f)){throw "HARNESS: missing source dependency $f"} }
  if($Ev.StartsWith($SourceRoot+[IO.Path]::DirectorySeparatorChar,[StringComparison]::Ordinal)){throw 'HARNESS: EvidenceRoot must be outside SourcePath'}
  if([IO.Directory]::Exists($Ev) -and @(Get-ChildItem -LiteralPath $Ev -Force).Count -gt 0){throw 'HARNESS: EvidenceRoot must be fresh and empty'}
  [void][IO.Directory]::CreateDirectory($Ev)
  $DepBefore=[ordered]@{}
  foreach($f in ($RequiredDeps+$ReferenceDeps)){ $DepBefore[$f]=$(if([IO.File]::Exists($f)){Get-Sha $f}else{'ABSENT'}) }
  # Real writer and real consumer/reconcile are the system under test; nothing is loaded from a sibling or snapshot.
  . $CommitFile
  . $ConsumerFile
  . $ReconcileFile
  if($script:LifecycleConsumerSource -cne $ConsumerFile){throw 'HARNESS: consumer dot-source path mismatch'}
} catch {
  [Console]::Error.WriteLine('HARNESS_ERROR '+$_.Exception.Message)
  exit 2
}

function Out-FxText { param([string]$Path,[string]$Text) [IO.File]::WriteAllText($Path,$Text,[Text.UTF8Encoding]::new($false)) }
function Out-FxJson { param([string]$Path,$Obj) Out-FxText $Path (ConvertTo-Json -InputObject $Obj -Depth 8) }
function Assert-True { param($Cond,[string]$Msg) if(-not $Cond){throw "ASSERT: $Msg"} }
function Assert-Eq { param($Actual,$Expected,[string]$Msg) if("$Actual" -cne "$Expected"){throw "ASSERT: $Msg (expected '$Expected', got '$Actual')"} }
function Get-Prop {
  param($O,[string]$N)
  if($null -eq $O){return $null}
  if($O -is [Collections.IDictionary]){ if($O.Contains($N)){return $O[$N]}; return $null }
  if(@($O.PSObject.Properties.Name) -ccontains $N){return $O.$N}
  return $null
}
function Read-RawRows {
  # Parsed with -DateKind String so unrelated rows are compared without date conversion.
  param([string]$Path)
  $p=ConvertFrom-Json -InputObject ([IO.File]::ReadAllText($Path)) -NoEnumerate -DateKind String
  if($p -isnot [array]){$p=@($p)}
  return ,$p
}
function Get-RowJson { param($Row) ConvertTo-Json -InputObject $Row -Depth 10 -Compress }

# ---- invented fixture constants (public text uses only the characters the real validators allow) ----
$FxTask='SYNTH-TASK-1'; $FxTitle='Synthetic fixture title'; $FxRepo='hakanduyar/software-factory'; $FxIssue=9067
$FxUrl="https://github.com/$FxRepo/issues/$FxIssue"
$FxMarker='factory-task-'+(Get-TextSha $FxTask)
$FxIssueTail='Unowned discussion paragraph. MOCK/NOT_LIVE synthetic fixture; this text must survive every update.'
$FxNoteHead="# Synthetic note heading (MOCK/NOT_LIVE)`nUnrelated prose above the managed block.`n"
$FxNoteTail='Trailing prose below the managed block, preserved.'
$Rev7=@{Rev=7;Status='IN_PROGRESS';Next='RUN_FOCUSED_CHECKS';Summary='Synthetic fixture summary for offline test only.'}
$Rev8=@{Rev=8;Status='WAITING_FOR_REVIEW';Next='INDEPENDENT_REVIEW';Summary='Synthetic updated summary for offline test only.'}
$Rev9=@{Rev=9;Status='IN_PROGRESS';Next='RESUME_AUTHORIZED_WORK';Summary='Synthetic revision nine summary for offline test only.'}

function New-FxCanonical { param($D) [ordered]@{taskId=$FxTask;canonicalRevision=$D.Rev;publicTitle=$FxTitle;publicSummary=$D.Summary;publicStatus=$D.Status;nextAction=$D.Next} }
function Get-FxRegion { param($D) "<!-- factory-task-status:start -->`nTask: $FxTask`nVersion: $($D.Rev)`nStatus: $($D.Status)`nNext action: $($D.Next)`nSummary: $($D.Summary)`n<!-- factory-task-status:end -->" }
function Get-FxIssueBody { param($D) "<!-- $FxMarker -->`n`n"+(Get-FxRegion $D)+"`n`n$FxIssueTail" }
function Get-FxNoteText {
  # $Updated=$true adds the generated Title/Summary header fields the real note writer owns.
  param($D,[bool]$Updated)
  $hdr=@("Task: $FxTask","Status: $($D.Status)","GitHub: $FxUrl",'Issue state: OPEN',"Canonical version: $($D.Rev)","Next action: $($D.Next)")
  if($Updated){$hdr+=@("Title: $FxTitle","Summary: $($D.Summary)")}
  return $FxNoteHead+"<!-- factory-task:$($FxTask):start -->`n"+($hdr -join "`n")+"`n`nAcceptance criteria (frozen v1):`n- Synthetic criterion preserved`n<!-- factory-task:$($FxTask):end -->`n"+$FxNoteTail
}
function Get-FxGithubProof { param($D) 'readback:'+(Get-TextSha ($FxTitle+"`n"+(Get-FxIssueBody $D))) }
function Get-FxNoteProof { param($D) 'bytes:'+(Get-TextSha (Get-FxNoteText $D $true)) }

function New-FxRow {
  param($Task,$Digest,$RunId,$Dest,$Status='AWAITING_CONTROLLER',$Attempt=0,$Delivery='PENDING',$Proof=$null,[hashtable]$Extra=@{})
  $key=Get-EventKey -TaskId $Task -PayloadSha256 $Digest -RunId $RunId -Status $Status -Attempt $Attempt
  $o=[ordered]@{key=$key;taskId=$Task;payloadSha256=$Digest;runId=$RunId;destination=$Dest;status=$Status;attempt=$Attempt;deliveryStatus=$Delivery;proof=$Proof}
  foreach($k in $Extra.Keys){$o[$k]=$Extra[$k]}
  return [pscustomobject]$o
}
function New-FxUnrelatedRow { New-FxRow -Task 'SYNTH-OTHER' -Digest ('a'*64) -RunId 'synth-other-run' -Dest 'github' -Status 'FAILED' -Attempt 1 -Extra @{updatedAt='2026-01-01T00:00:00Z';consentEligibility=$null;reconciliationSignal=$false;synthNote='unrelated metadata'} }

function Add-Raw { param($C,[string]$Label,$Obj) Out-FxJson (Join-Path $C.dir "raw-$Label.json") $Obj }

function New-FxCase {
  param([string]$Name)
  $dir=Join-Path $Ev $Name
  $c=@{name=$Name;dir=$dir;state=(Join-Path $dir 'state');vault=(Join-Path $dir 'vault');temp=(Join-Path $dir 'temp')}
  foreach($d in @($c.state,$c.vault,$c.temp)){[void][IO.Directory]::CreateDirectory($d)}
  $c.canonical=Join-Path $dir 'canonical.json'
  $c.outbox=Join-Path $c.state 'outbox.json'
  $c.journal=Join-Path $c.state 'lifecycle-update.journal.json'
  $c.note=Join-Path $c.vault 'task.md'
  $c.otherNote=Join-Path $c.vault 'unrelated.md'
  $c.exe=Join-Path $dir 'gh-fixture.bin'
  $c.mapping=Join-Path $dir 'mapping.json'
  $c.beforeIssue=Join-Path $dir 'before-issue.json'
  $c.beforeNote=Join-Path $dir 'before-note.md'
  Out-FxJson (Join-Path $dir 'fixture-manifest.json') ([ordered]@{label='MOCK/NOT_LIVE';case=$Name;authority='synthetic offline fixture only'})
  Out-FxJson $c.canonical (New-FxCanonical $Rev7)
  Out-FxText $c.exe 'MOCK/NOT_LIVE fixture executable pin target; never executed'
  Out-FxJson $c.mapping ([ordered]@{taskId=$FxTask;repo=$FxRepo;issueNumber=$FxIssue;url=$FxUrl;stableMarker=$FxMarker;canonicalRevision=7})
  Out-FxJson $c.beforeIssue ([ordered]@{title=$FxTitle;body=(Get-FxIssueBody $Rev7)})
  Out-FxText $c.beforeNote (Get-FxNoteText $Rev7 $false)
  Out-FxText $c.note (Get-FxNoteText $Rev7 $false)
  Out-FxText $c.otherNote "Unrelated vault note, MOCK/NOT_LIVE; never part of the managed region.`n"
  Write-OutboxAtomic $c.outbox @((New-FxUnrelatedRow))
  $c.remote=@{number=$FxIssue;url=$FxUrl;state='OPEN';title=$FxTitle;body=(Get-FxIssueBody $Rev7)}
  $c.rec=@{views=0;edits=0;calls=[Collections.Generic.List[object]]::new()}
  return $c
}

# Request + independent admission for ONE real writer operation; strict production schemas, no validator bypass.
function New-FxWriterOp {
  param($C,[string]$OpId,$D,[string]$Idem)
  $newPath=Join-Path $C.dir "new-$OpId.json"; $pktPath=Join-Path $C.dir "packet-$OpId.json"
  $reqPath=Join-Path $C.dir "request-$OpId.json"; $admPath=Join-Path $C.dir "admission-$OpId.json"
  $opDir=Join-Path $C.state ('canonical-update-'+$OpId)
  Out-FxJson $newPath (New-FxCanonical $D)
  Out-FxJson $pktPath ([ordered]@{schema='TaskLifecycleMirrorPacket/v1';taskId=$FxTask;canonicalRevision=$D.Rev;eventType='UPDATE';idempotencyKey=$Idem;publicTitle=$FxTitle;publicSummary=$D.Summary;publicStatus=$D.Status;nextAction=$D.Next;destinations=@('github','note')})
  $pin=$null; if([IO.File]::Exists($C.outbox)){$pin=Get-Sha $C.outbox}
  $beforeSha=Get-Sha $C.canonical
  $ref={ param($p) [ordered]@{path=$p;sha256=(Get-Sha $p)} }
  Out-FxJson $reqPath ([ordered]@{schema='CanonicalLifecycleUpdateCommitRequest/v1';operationId=$OpId;taskId=$FxTask;canonicalPath=$C.canonical;expectedBeforeSha256=$beforeSha
    newCanonicalRef=(& $ref $newPath);packetRef=(& $ref $pktPath);enqueueRef=(& $ref $EnqueueFile);consumerRef=(& $ref $ConsumerFile);reconcileRef=(& $ref $ReconcileFile)
    stateDir=$C.state;outboxPath=$C.outbox;expectedOutboxSha256=$pin;operationDirectory=$opDir})
  Out-FxJson $admPath ([ordered]@{schema='CanonicalLifecycleUpdateCommitAdmission/v1';decision='ADMIT_CANONICAL_UPDATE_COMMIT';reviewer='synthetic-independent-reviewer';requestSha256=(Get-Sha $reqPath);operationId=$OpId;taskId=$FxTask
    beforeSha256=$beforeSha;afterSha256=(Get-Sha $newPath);packetSha256=(Get-Sha $pktPath);enqueueSha256=(Get-Sha $EnqueueFile);consumerSha256=(Get-Sha $ConsumerFile);reconcileSha256=(Get-Sha $ReconcileFile);captureSha256=(Get-Sha $CaptureFile)})
  return @{C=$C;OpId=$OpId;OpDir=$opDir;D=$D;NewPath=$newPath;NewSha=(Get-Sha $newPath);PacketPath=$pktPath;Idem=$Idem
    A=@{RequestPath=$reqPath;ExpectedRequestSha256=(Get-Sha $reqPath);AdmissionPath=$admPath;ExpectedAdmissionSha256=(Get-Sha $admPath)}}
}
function Invoke-FxCommit { param($Op) $a=$Op.A; Invoke-CanonicalLifecycleUpdateCommit @a }

function Get-FxExpect {
  # Digest and event keys through the consumer's own reader and key formula (the independent oracle).
  param($Op)
  $c=Read-LifecycleJson $Op.NewPath
  $digest=Get-LifecycleHash ([Text.Encoding]::UTF8.GetBytes(($c | ConvertTo-Json -Depth 8 -Compress)))
  $e=@{digest=$digest}
  foreach($d in @('github','note')){$e[$d]=Get-EventKey -TaskId $c.taskId -PayloadSha256 $digest -RunId ($Op.Idem+':'+$d) -Status 'AWAITING_CONTROLLER' -Attempt 0}
  return $e
}
function Assert-FxPair {
  param($Op,[int]$Total,[string]$Delivery,[hashtable]$Proofs=@{})
  $ex=Get-FxExpect $Op
  $rows=@(Read-Outbox $Op.C.outbox)
  Assert-Eq $rows.Count $Total 'outbox row count'
  foreach($d in @('github','note')){
    $m=@($rows | Where-Object {$_.key -ceq $ex[$d]})
    Assert-Eq $m.Count 1 "exactly one $d row for $($Op.OpId)"
    $row=$m[0]
    Assert-Eq $row.taskId $FxTask "$d taskId"
    Assert-Eq $row.destination $d "$d destination"
    Assert-Eq $row.runId ($Op.Idem+':'+$d) "$d runId"
    Assert-Eq $row.payloadSha256 $ex.digest "$d payload digest"
    Assert-Eq $row.status 'AWAITING_CONTROLLER' "$d status"
    Assert-Eq $row.attempt 0 "$d attempt"
    $want=$Delivery; if($Proofs.ContainsKey($d+'.delivery')){$want=$Proofs[$d+'.delivery']}
    Assert-Eq $row.deliveryStatus $want "$d deliveryStatus"
    if($want -ceq 'PENDING'){ Assert-True ($null -eq $row.proof) "$d proof null" }
    else { Assert-Eq $row.proof $Proofs[$d] "$d proof" }
  }
}
function Assert-FxWriterBindings {
  # The persisted writer intent binds task, revision, packet, canonical bytes and the generated keys.
  param($Op)
  $ex=Get-FxExpect $Op
  $intent=Read-LifecycleJson (Join-Path $Op.OpDir 'intent.json')
  Assert-Eq $intent['taskId'] $FxTask 'intent task'
  Assert-Eq $intent['afterSha256'] $Op.NewSha 'intent new canonical'
  Assert-Eq $intent['packetSha256'] (Get-Sha $Op.PacketPath) 'intent packet'
  Assert-Eq $intent['requestSha256'] $Op.A.ExpectedRequestSha256 'intent request'
  Assert-Eq $intent['digest'] $ex.digest 'intent digest'
  Assert-Eq $intent['keys']['github'] $ex.github 'intent github key'
  Assert-Eq $intent['keys']['note'] $ex.note 'intent note key'
  $pk=Read-LifecycleJson $Op.PacketPath; $cn=Read-LifecycleJson $Op.NewPath
  Assert-Eq $pk['canonicalRevision'] $Op.D.Rev 'packet revision'
  Assert-Eq $cn['canonicalRevision'] $Op.D.Rev 'canonical revision'
  Assert-Eq $pk['idempotencyKey'] $Op.Idem 'packet idempotency key'
  $status=Read-LifecycleJson (Join-Path $Op.OpDir 'status.json')
  Assert-Eq $status['phase'] 'ENQUEUED' 'writer phase'
}

# Delivery release/review/native request built from the writer's actual files and current outbox bytes.
function New-FxRelease {
  param($C,$Op,[string]$Tag,[string]$Recovery)
  $dd=Join-Path $C.dir ('release-'+$Tag); [void][IO.Directory]::CreateDirectory($dd)
  $ref={ param($p) [ordered]@{path=$p;sha256=(Get-Sha $p)} }
  $pkt=& $ref $Op.PacketPath; $cons=& $ref $ConsumerFile; $trn=& $ref $TransportFile; $exe=& $ref $C.exe
  $reviewPath=Join-Path $dd 'review.json'; $nativePath=Join-Path $dd 'native.json'; $releasePath=Join-Path $dd 'release.json'
  Out-FxJson $reviewPath ([ordered]@{schema='LifecycleIndependentReview/v1';decision='ADMIT';packetSha256=$pkt.sha256;consumerSha256=$cons.sha256;transportSha256=$trn.sha256})
  $review=& $ref $reviewPath
  Out-FxJson $nativePath ([ordered]@{schema='LifecycleNativeRequest/v1';action='UPDATE';packetSha256=$pkt.sha256;reviewSha256=$review.sha256;consumerSha256=$cons.sha256;transportSha256=$trn.sha256;executableSha256=$exe.sha256;stateDir=$C.state;notePath=$C.note;outboxPath=$C.outbox})
  $native=& $ref $nativePath
  Out-FxJson $releasePath ([ordered]@{schema='TaskLifecycleUpdateRelease/v1';packet=$pkt;canonical=(& $ref $C.canonical);mapping=(& $ref $C.mapping);beforeIssue=(& $ref $C.beforeIssue);beforeNote=(& $ref $C.beforeNote)
    review=$review;nativeRequest=$native;consumer=$cons;transport=$trn;executable=$exe;stateDir=$C.state;vaultRoot=$C.vault;notePath=$C.note;outboxPath=$C.outbox
    journalPath=$C.journal;canonicalLease=($C.canonical+'.lock');publisherLease=(Join-Path $C.state 'publisher.lock');tempRoot=$C.temp;outboxSha256=(Get-Sha $C.outbox);recovery=$Recovery})
  return @{ReleasePath=$releasePath;ExpectedReleaseSha256=(Get-Sha $releasePath);ExpectedReviewSha256=$review.sha256;ExpectedNativeRequestSha256=$native.sha256;ReconcilePath=$ReconcileFile}
}

# The only external substitution: records every invocation and serves/edits the synthetic remote issue.
function New-FxRunner {
  param($C)
  $remote=$C.remote; $rec=$C.rec
  return {
    param($exe,$argv,$deadline,$stdoutCap,$stderrCap)
    $rec.calls.Add([pscustomobject]@{exe=[string]$exe;argv=@($argv | ForEach-Object {[string]$_})})
    $ok={ param($out) [pscustomobject]@{exitCode=[int]0;timedOut=$false;stdout=[string]$out;stdoutTruncated=$false;stderrTruncated=$false} }
    if($argv[0] -ceq 'issue' -and $argv[1] -ceq 'view'){
      $rec.views++
      return (& $ok (ConvertTo-Json -InputObject ([ordered]@{number=$remote.number;url=$remote.url;state=$remote.state;title=$remote.title;body=$remote.body}) -Compress))
    }
    if($argv[0] -ceq 'issue' -and $argv[1] -ceq 'edit'){
      $rec.edits++
      $ti=[Array]::IndexOf($argv,'--title'); $bi=[Array]::IndexOf($argv,'--body-file')
      $remote.title=[string]$argv[$ti+1]
      $remote.body=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes([string]$argv[$bi+1]))
      return (& $ok $remote.url)
    }
    throw 'UNEXPECTED_CONNECTOR_OPERATION'
  }.GetNewClosure()
}
function Invoke-FxDelivery {
  param($C,$Rel)
  $a=@{}; foreach($k in $Rel.Keys){$a[$k]=$Rel[$k]}
  return (Invoke-AdmittedTaskLifecycleUpdate @a -ProcessRunner (New-FxRunner $C))
}
function Assert-FxOnlyUpdateCalls {
  # No CREATE/CLOSE/api or any other operation: only 'issue view' and 'issue edit' on the one repo, via the pinned fake exe.
  param($C)
  foreach($call in $C.rec.calls){
    Assert-Eq $call.exe $C.exe 'runner executable'
    Assert-True ($call.argv[0] -ceq 'issue' -and $call.argv[1] -cin @('view','edit')) ('only issue view/edit allowed, got '+($call.argv -join ' '))
    Assert-True (@($call.argv) -ccontains $FxRepo) 'repo argument'
  }
}
function Get-FxRemoteSig { param($C) "$($C.remote.state)|$($C.remote.title)|$($C.remote.body)" }
function Get-FxFlags {
  param($C,[string]$Idem)
  $j=Read-LifecycleJson $C.journal
  return @{journal=$j;event=$j.events[$Idem]}
}
function Assert-FxFlags {
  param($Evt,[bool]$Gs,[bool]$Ns,[bool]$Ga,[bool]$Na)
  Assert-True ($null -ne $Evt -and $Evt['githubSent'] -eq $Gs -and $Evt['noteSent'] -eq $Ns -and $Evt['githubAck'] -eq $Ga -and $Evt['noteAck'] -eq $Na) ('delivery flags '+(ConvertTo-Json -InputObject $Evt -Compress -Depth 6))
}
function Assert-FxTempClean { param($C) Assert-Eq @(Get-ChildItem -LiteralPath $C.temp -Force).Count 0 'transport temp root empty' }
function Save-FxCaseEvidence {
  param($C)
  Add-Raw $C 'runner-calls' @($C.rec.calls)
  Add-Raw $C 'runner-counts' ([ordered]@{views=$C.rec.views;edits=$C.rec.edits;calls=$C.rec.calls.Count})
  Add-Raw $C 'remote-final' ([ordered]@{number=$C.remote.number;url=$C.remote.url;state=$C.remote.state;title=$C.remote.title;body=$C.remote.body})
}

$Results=[Collections.Generic.List[object]]::new()
function Test-Step {
  param([string]$Name,[scriptblock]$Body)
  try{ & $Body; $Results.Add([pscustomobject]@{name=$Name;verdict='PASS';error=''}); Write-Host "PASS $Name" }
  catch{ $Results.Add([pscustomobject]@{name=$Name;verdict='FAIL';error=$_.Exception.Message}); Write-Host "FAIL $Name :: $($_.Exception.Message)" }
}
$OriginalAtomicWriter=${function:Write-LifecycleAtomic}
$OriginalAtomicWriterText=$OriginalAtomicWriter.ToString()

$Case1='case1-writer-rows-delivered-by-consumer'
$Case2='case2-note-failure-recovery-and-replay'
$Case3='case3-stale-release-after-newer-revision'
$Case4='case4-integrity-and-restoration'

Test-Step $Case1 {
  $c=New-FxCase 'case1'
  $op=New-FxWriterOp $c 'op-rev8' $Rev8 'synth-idem-8'
  $w=Invoke-FxCommit $op; Add-Raw $c 'writer-result' $w
  Assert-Eq $w.status 'ENQUEUED' 'writer status'; Assert-Eq $w.code 'ENQUEUED_VERIFIED' 'writer code'
  Assert-Eq (Get-Sha $c.canonical) $op.NewSha 'canonical is the approved new bytes'
  Assert-FxPair $op 3 'PENDING'
  Assert-FxWriterBindings $op
  # Delivery fixture is built from these generated files/rows, never from a consumer-shaped outbox.
  $outboxAfterWriter=Get-Sha $c.outbox
  $rawBefore=Read-RawRows $c.outbox
  $otherBefore=Get-Sha $c.otherNote; $canonBefore=Get-Sha $c.canonical
  $rel=New-FxRelease $c $op 'initial' 'INITIAL'
  Assert-Eq $rel.ExpectedReleaseSha256 (Get-Sha $rel.ReleasePath) 'release pin'
  $r=Invoke-FxDelivery $c $rel; Add-Raw $c 'delivery-result' $r
  Assert-Eq $r.status 'DELIVERED' 'delivery status'; Assert-Eq $r.code 'READBACK_ACK' 'delivery code'
  Assert-True ($r.githubAck -eq $true -and $r.noteAck -eq $true) 'both ACKs reported'
  Assert-Eq $c.rec.edits 1 'exactly one GitHub EDIT'
  Assert-True ($c.rec.views -ge 2) 'initial read and edit readback happened'
  Assert-FxOnlyUpdateCalls $c
  Assert-Eq $c.remote.state 'OPEN' 'issue stays open (no CLOSE)'
  Assert-Eq $c.remote.title $FxTitle 'remote title'
  Assert-Eq $c.remote.body (Get-FxIssueBody $Rev8) 'remote body is exactly the managed region swap'
  Assert-True ($c.remote.body.EndsWith($FxIssueTail,[StringComparison]::Ordinal)) 'unowned issue text preserved'
  $noteText=[IO.File]::ReadAllText($c.note)
  Assert-Eq $noteText (Get-FxNoteText $Rev8 $true) 'note exactly the managed header update'
  Assert-True ($noteText.StartsWith($FxNoteHead,[StringComparison]::Ordinal) -and $noteText.EndsWith($FxNoteTail,[StringComparison]::Ordinal)) 'unowned note prose preserved'
  Assert-Eq (Get-Sha $c.otherNote) $otherBefore 'unrelated vault file unchanged'
  Assert-Eq (Get-Sha $c.canonical) $canonBefore 'canonical unchanged by delivery'
  Assert-FxPair $op 3 'DELIVERED' @{github=(Get-FxGithubProof $Rev8);note=(Get-FxNoteProof $Rev8)}
  $rawAfter=Read-RawRows $c.outbox
  Assert-Eq (Get-RowJson $rawAfter[0]) (Get-RowJson $rawBefore[0]) 'unrelated outbox row unchanged'
  Assert-True ([IO.File]::ReadAllText($c.outbox).Contains('2026-01-01T00:00:00Z')) 'unrelated date text not reformatted'
  Assert-True ((Get-Sha $c.outbox) -cne $outboxAfterWriter) 'outbox advanced by ACKs'
  $g=Get-FxFlags $c $op.Idem
  Assert-Eq $g.journal['schema'] 'LifecycleUpdateJournal/v2' 'journal schema'
  Assert-FxFlags $g.event $true $true $true $true
  Assert-True ($null -eq $g.event['lastFailure']) 'no failure recorded'
  Assert-Eq $g.journal['heads'][$FxTask]['revision'] 8 'head revision'
  Assert-FxTempClean $c
  Save-FxCaseEvidence $c
}

Test-Step $Case2 {
  $c=New-FxCase 'case2'
  $op=New-FxWriterOp $c 'op-rev8' $Rev8 'synth-idem-8'
  $w=Invoke-FxCommit $op; Add-Raw $c 'writer-result' $w
  Assert-Eq $w.status 'ENQUEUED' 'writer status'
  Assert-FxPair $op 3 'PENDING'
  $otherBefore=Get-Sha $c.otherNote
  $rawBefore=Read-RawRows $c.outbox
  $rel1=New-FxRelease $c $op 'initial' 'INITIAL'
  # Test-only fault: scoped to the owned note path, restored in finally; no product edit or hook.
  $script:FaultOrig=$OriginalAtomicWriter; $script:FaultPath=$c.note; $script:FaultHits=0
  ${function:script:Write-LifecycleAtomic}={ param([string]$Path,[byte[]]$Bytes)
    if($Path -ceq $script:FaultPath){ $script:FaultHits++; throw [IO.IOException]::new('INJECTED_WRITE_FAILURE') }
    & $script:FaultOrig -Path $Path -Bytes $Bytes }
  $r1=$null
  try{ $r1=Invoke-FxDelivery $c $rel1 }
  finally{ ${function:script:Write-LifecycleAtomic}=$OriginalAtomicWriter }
  $hits=$script:FaultHits; $script:FaultOrig=$null; $script:FaultPath=$null; $script:FaultHits=0
  Add-Raw $c 'partial-result' $r1
  Assert-Eq (${function:Write-LifecycleAtomic}).ToString() $OriginalAtomicWriterText 'atomic writer restored'
  Assert-Eq $hits 1 'exactly one injected note write failure'
  Assert-Eq $r1.status 'PENDING' 'partial status'; Assert-True ($r1.automaticRetry -eq $false) 'no automatic retry'
  Assert-Eq $c.rec.edits 1 'GitHub EDIT happened once before the failure'
  Assert-Eq $c.remote.body (Get-FxIssueBody $Rev8) 'GitHub side already converged'
  Assert-Eq ([IO.File]::ReadAllText($c.note)) (Get-FxNoteText $Rev7 $false) 'note still the old bytes'
  Assert-True (@(Get-ChildItem -LiteralPath $c.vault -Force | Where-Object {$_.Name -like '*.tmp-*'}).Count -eq 0) 'no stray note temp file'
  Assert-FxPair $op 3 'PENDING' @{github=(Get-FxGithubProof $Rev8);'github.delivery'='DELIVERED'}
  $g=Get-FxFlags $c $op.Idem
  Assert-FxFlags $g.event $true $true $true $false
  $f=$g.event['lastFailure']
  Assert-True ($null -ne $f -and $f['code'] -ceq 'NOTE_WRITE_FAILED' -and $f['phase'] -ceq 'NOTE_WRITE' -and $f['destination'] -ceq 'note' -and $f['operation'] -ceq 'WRITE' -and $null -eq $f['diagnostic']) 'sanitized partial failure record'
  Assert-Eq $g.journal['heads'].Count 0 'no head recorded for a partial event'
  # Preserve the actual partial journal/rows for review.
  [IO.File]::Copy($c.journal,(Join-Path $c.dir 'partial-journal.json'),$false)
  [IO.File]::Copy($c.outbox,(Join-Path $c.dir 'partial-outbox.json'),$false)
  $partialFailureJson=ConvertTo-Json -InputObject $f -Depth 6 -Compress
  # Explicit fresh current-state RECONCILE_MISSING release pins the actual partial outbox.
  $rel2=New-FxRelease $c $op 'reconcile' 'RECONCILE_MISSING'
  $r2=Invoke-FxDelivery $c $rel2; Add-Raw $c 'reconcile-result' $r2
  Assert-Eq $r2.status 'DELIVERED' 'reconcile status'; Assert-Eq $r2.code 'READBACK_ACK' 'reconcile code'
  Assert-Eq $c.rec.edits 1 'GitHub EDIT count did not increase on recovery'
  Assert-FxOnlyUpdateCalls $c
  Assert-Eq ([IO.File]::ReadAllText($c.note)) (Get-FxNoteText $Rev8 $true) 'missing note converged'
  Assert-Eq $c.remote.body (Get-FxIssueBody $Rev8) 'remote body unchanged by recovery'
  Assert-FxPair $op 3 'DELIVERED' @{github=(Get-FxGithubProof $Rev8);note=(Get-FxNoteProof $Rev8)}
  $g=Get-FxFlags $c $op.Idem
  Assert-FxFlags $g.event $true $true $true $true
  Assert-Eq (ConvertTo-Json -InputObject $g.event['lastFailure'] -Depth 6 -Compress) $partialFailureJson 'original partial history retained'
  Assert-Eq $g.journal['heads'][$FxTask]['revision'] 8 'head recorded after convergence'
  Assert-Eq (Get-RowJson (Read-RawRows $c.outbox)[0]) (Get-RowJson $rawBefore[0]) 'unrelated outbox row unchanged'
  Assert-Eq (Get-Sha $c.otherNote) $otherBefore 'unrelated vault file unchanged'
  # Exact supported already-delivered replay: fresh INITIAL release over the converged state is DEBOUNCED.
  $rel3=New-FxRelease $c $op 'replay' 'INITIAL'
  $snap=@{outbox=(Get-Sha $c.outbox);journal=(Get-Sha $c.journal);note=(Get-Sha $c.note);other=(Get-Sha $c.otherNote);remote=(Get-FxRemoteSig $c);canonical=(Get-Sha $c.canonical)}
  $r3=Invoke-FxDelivery $c $rel3; Add-Raw $c 'replay-result' $r3
  Assert-Eq $r3.status 'DELIVERED' 'replay status'; Assert-Eq $r3.code 'DEBOUNCED' 'replay code'
  Assert-Eq $c.rec.edits 1 'replay issued no duplicate EDIT'
  Assert-Eq (Get-Sha $c.outbox) $snap.outbox 'replay outbox unchanged'
  Assert-Eq (Get-Sha $c.journal) $snap.journal 'replay journal unchanged'
  Assert-Eq (Get-Sha $c.note) $snap.note 'replay note unchanged'
  Assert-Eq (Get-Sha $c.otherNote) $snap.other 'replay unrelated vault file unchanged'
  Assert-Eq (Get-FxRemoteSig $c) $snap.remote 'replay remote unchanged'
  Assert-Eq (Get-Sha $c.canonical) $snap.canonical 'replay canonical unchanged'
  Assert-FxOnlyUpdateCalls $c
  Assert-FxTempClean $c
  Save-FxCaseEvidence $c
}

Test-Step $Case3 {
  $c=New-FxCase 'case3'
  $opA=New-FxWriterOp $c 'op-rev8' $Rev8 'synth-idem-8'
  $wA=Invoke-FxCommit $opA; Add-Raw $c 'writer-result-rev8' $wA
  Assert-Eq $wA.status 'ENQUEUED' 'rev8 writer status'
  # Older admission is prepared against the revision-8 state BEFORE the newer revision is committed.
  $relA=New-FxRelease $c $opA 'rev8-stale' 'INITIAL'
  $opB=New-FxWriterOp $c 'op-rev9' $Rev9 'synth-idem-9'
  $wB=Invoke-FxCommit $opB; Add-Raw $c 'writer-result-rev9' $wB
  Assert-Eq $wB.status 'ENQUEUED' 'rev9 writer status'
  Assert-Eq (Get-Sha $c.canonical) $opB.NewSha 'canonical is revision 9'
  Assert-True ($opA.NewSha -cne $opB.NewSha) 'distinct revisions'
  Assert-FxPair $opA 5 'PENDING'; Assert-FxPair $opB 5 'PENDING'
  Assert-FxWriterBindings $opA; Assert-FxWriterBindings $opB
  $exA=Get-FxExpect $opA; $exB=Get-FxExpect $opB
  Assert-True ($exA.github -cne $exB.github -and $exA.note -cne $exB.note) 'distinct event keys per revision'
  $snap=@{outbox=(Get-Sha $c.outbox);canonical=(Get-Sha $c.canonical);note=(Get-Sha $c.note);other=(Get-Sha $c.otherNote);remote=(Get-FxRemoteSig $c)
    aIntent=(Get-Sha (Join-Path $opA.OpDir 'intent.json'));aStatus=(Get-Sha (Join-Path $opA.OpDir 'status.json'))
    bIntent=(Get-Sha (Join-Path $opB.OpDir 'intent.json'));bStatus=(Get-Sha (Join-Path $opB.OpDir 'status.json'))}
  $r=Invoke-FxDelivery $c $relA; Add-Raw $c 'stale-delivery-result' $r
  Assert-Eq $r.status 'REFUSED' 'stale release status'; Assert-Eq $r.code 'PIN_DRIFT' 'stale release code'
  Assert-True ($null -eq (Get-Prop $r 'githubAck') -and $null -eq (Get-Prop $r 'noteAck')) 'no ACK claimed'
  Assert-Eq $c.rec.calls.Count 0 'zero ProcessRunner invocations'
  Assert-Eq $c.rec.edits 0 'zero edits'; Assert-Eq $c.rec.views 0 'zero reads'
  Assert-Eq (Get-Sha $c.canonical) $snap.canonical 'no canonical rollback'
  Assert-Eq (Get-Sha $c.canonical) $opB.NewSha 'current canonical still revision 9'
  Assert-Eq (Get-Sha $c.outbox) $snap.outbox 'outbox unchanged'
  Assert-True (-not [IO.File]::Exists($c.journal)) 'no journal created by a refused release'
  Assert-Eq (Get-Sha $c.note) $snap.note 'note unchanged'; Assert-Eq (Get-Sha $c.otherNote) $snap.other 'unrelated vault file unchanged'
  Assert-Eq (Get-FxRemoteSig $c) $snap.remote 'remote unchanged'
  Assert-True (@(Read-Outbox $c.outbox | Where-Object {$_.deliveryStatus -ceq 'DELIVERED'}).Count -eq 0) 'no false ACK in outbox'
  Assert-Eq (Get-Sha (Join-Path $opA.OpDir 'intent.json')) $snap.aIntent 'rev8 intent preserved'
  Assert-Eq (Get-Sha (Join-Path $opA.OpDir 'status.json')) $snap.aStatus 'rev8 status preserved'
  Assert-Eq (Get-Sha (Join-Path $opB.OpDir 'intent.json')) $snap.bIntent 'rev9 intent preserved'
  Assert-Eq (Get-Sha (Join-Path $opB.OpDir 'status.json')) $snap.bStatus 'rev9 status preserved'
  Assert-FxTempClean $c
  Save-FxCaseEvidence $c
}

Test-Step $Case4 {
  foreach($f in $DepBefore.Keys){
    $now=$(if([IO.File]::Exists($f)){Get-Sha $f}else{'ABSENT'})
    Assert-Eq $now $DepBefore[$f] "dependency unchanged $f"
  }
  Assert-Eq (${function:Write-LifecycleAtomic}).ToString() $OriginalAtomicWriterText 'test fault wrapper restored'
  Assert-True ($null -eq (Get-Alias -Name Invoke-CmFaultPoint -ErrorAction SilentlyContinue)) 'writer fault alias not installed'
  foreach($case in @('case1','case2','case3')){
    $dir=Join-Path $Ev $case
    Assert-True ([IO.File]::Exists((Join-Path $dir 'fixture-manifest.json'))) "$case labelled MOCK/NOT_LIVE"
    foreach($child in @(Get-ChildItem -LiteralPath $dir -Force -Recurse | ForEach-Object {$_.FullName})){
      Assert-True ($child.StartsWith($Ev+[IO.Path]::DirectorySeparatorChar,[StringComparison]::Ordinal)) 'fixtures stay under EvidenceRoot'
    }
  }
}

$Expected=@($Case1,$Case2,$Case3,$Case4)
$Missing=@($Expected | Where-Object {$Results.name -cnotcontains $_})
$Failed=@($Results | Where-Object {$_.verdict -cne 'PASS'})
$Overall=$(if($Failed.Count -eq 0 -and $Missing.Count -eq 0 -and $Results.Count -eq $Expected.Count){'PASS'}else{'FAIL'})
Out-FxJson (Join-Path $Ev 'results.json') @($Results)
Out-FxJson (Join-Path $Ev 'summary.json') ([ordered]@{label='MOCK/NOT_LIVE';overall=$Overall;expectedCases=$Expected;missingCases=$Missing;passed=($Results.Count-$Failed.Count);failed=$Failed.Count;cases=@($Results)})
Write-Host ("canonical-update-delivery-integration: {0} ({1} passed, {2} failed, {3} missing; synthetic offline fixtures; not live delivery proof)" -f $Overall,($Results.Count-$Failed.Count),$Failed.Count,$Missing.Count)
if($Overall -cne 'PASS'){exit 1}
